# Model 2 of the 3D non-matching coupled Poisson example (tetrahedra):
# [0.5,1.0] x [0,1] x [0,1], 2 x 2 x 2 cubes, generated by cubemesh.
# Executed by pdeapp.py, which defines pde, mesh, exasim and numpy.
pde[1], mesh[1] = exasim.initializeexasim()

pde[1]['model'] = "ModelD"
pde[1]['modelfile'] = "pdemodel2"
pde[1]['modelnumber'] = 2
pde[1]['Cxxpreprocessing'] = 1
pde[1]['mpiprocs'] = 1
pde[1]['hybrid'] = 1
pde[1]['porder'] = 2
pde[1]['pgauss'] = 4
pde[1]['physicsparam'] = numpy.array([1.0])
pde[1]['tau'] = numpy.array([1.0])
pde[1]['NLiter'] = 4
pde[1]['NLtol'] = 1e-12
pde[1]['linearsolvertol'] = 1e-12
pde[1]['matvectol'] = 1e-12
pde[1]['GMRESrestart'] = 250
pde[1]['linearsolveriter'] = 600
pde[1]['interfacetype'] = 1

mesh[1]['p'], mesh[1]['t'] = exasim.Mesh.cubemesh(2, 2, 2, 0)[0:2]
mesh[1]['p'][0, :] = 0.5 + 0.5 * mesh[1]['p'][0, :]   # map x to [0.5,1]
# Boundaries: y = 0, x = 1, y = 1, x = 0.5, z = 0, z = 1
mesh[1]['boundaryexpr'] = [lambda p: abs(p[1, :]) < 1e-8, lambda p: abs(p[0, :] - 1) < 1e-8,
                          lambda p: abs(p[1, :] - 1) < 1e-8, lambda p: abs(p[0, :] - 0.5) < 1e-8,
                          lambda p: abs(p[2, :]) < 1e-8, lambda p: abs(p[2, :] - 1) < 1e-8]
mesh[1]['boundarycondition'] = numpy.array([1, 1, 1, 2, 1, 1])
mesh[1]['interfacecondition'] = numpy.array([0, 0, 0, 1, 0, 0])   # boundary 4 is the coupled interface
pde[1]['interfacefluxmap'] = numpy.array([1])
